// Reverse String using a Stack
var stack = AnimatedStack<String>()
let chars = ["H", "e", "l", "l", "o"]

func reverseString(_ sequence: [String], s: inout AnimatedStack<String>) -> [String] {
    for ch in sequence {
        s.push(ch)
    }
    var reversed: [String] = []
    while !s.isEmpty {
        if let popped = s.pop() {
            reversed.append(popped)
        }
    }
    return reversed
}

let reversed = reverseString(chars, s: &stack)
